Tests.EqualCheck("match first alternative top-level", true, matchPattern("cat", "cat|dog"))
Tests.EqualCheck("match second alternative top-level", true, matchPattern("dog", "cat|dog"))
Tests.EqualCheck("do not match neither top-level alternative", false, matchPattern("fish", "cat|dog"))
Tests.EqualCheck("match grouped alternation first option", true, matchPattern("I love cats!", "I love (cats|dogs)!"))
Tests.EqualCheck("match grouped alternation second option", true, matchPattern("I love dogs!", "I love (cats|dogs)!"))
Tests.EqualCheck("do not match grouped alternation invalid option", false, matchPattern("I love birds!", "I love (cats|dogs)!"))
Tests.EqualCheck("match alternation with three options", true, matchPattern("apple", "(apple|banana|cherry)"))
Tests.EqualCheck("match alternation anchored", true, matchPattern("cat", "^(cat|dog)$"))
Tests.EqualCheck("do not match alternation anchored with extra chars", false, matchPattern("cats", "^(cat|dog)$"))
Tests.EqualCheck("match alternation combined with digits quantifier", true, matchPattern("3 dogs", `^\d+ (cat|dog)s?$`))
Tests.EqualCheck("match alternation combined with digits quantifier singular", true, matchPattern("1 cat", `^\d+ (cat|dog)s?$`))
Tests.EqualCheck("do not match alternation combined if wrong animal", false, matchPattern("1 bird", `^\d+ (cat|dog)s?$`))
Tests.EqualCheck("top-level alternation with anchors", true, matchPattern("category", "^cat|dog$"))
Tests.EqualCheck("top-level alternation second anchor", true, matchPattern("hotdog", "^cat|dog$"))
Tests.EqualCheck("top-level alternation neither matches", false, matchPattern("my cat is cute", "^cat|dog$"))
Tests.EqualCheck("empty pattern matches any line", true, matchPattern("hello", ""))
